#define PK_LEN 7

/**
 * Validates that the primary key adheres strictly to the "GRXX-YY" format,
 * where XX is a 2-digit group number and YY is a 2-digit run number.
 */
static int validate_pk(const char *pk) {
    if (pk == NULL || strlen(pk)< PK_LEN) {
        return 0;
    }
    
    /* Check "GR" prefix
    if (pk[0] != 'G' || pk[1] != 'R') {
        return 0;
    }*/
    
    // Check 2-digit group number
    if (!isdigit((unsigned char)pk[2]) || !isdigit((unsigned char)pk[3])) {
    	print_error("Group number does not consist of digits\n");
        return 0;
    }
    
    /* Check delimiter
    if (pk[4] != '-') {
        return 0;
    }*/
    
    // Check 2-digit run number
    if (!isdigit((unsigned char)pk[5]) || !isdigit((unsigned char)pk[6])) {
    	print_error("Run number does not consist of digits\n");
        return 0;
    }

    return 1;
}

/**
 * Opens and returns a FILE pointer for the first file in the current directory
 * whose filename begins with the given primary key (e.g., "GR01-02_data.csv").
 *
 * Returns NULL if the primary key is invalid or if no matching file exists.
 */
FILE* file_open(const char *pk,struct hplc_run_metadata*meta) {
    if (!validate_pk(pk)) {
        return NULL;
    }

#if defined(_WIN32) || defined(_WIN64)
    WIN32_FIND_DATAA find_data;
    char search_pattern[PK_LEN + 2]; // "GRXX-YY*" + '\0'
    
    snprintf(search_pattern, sizeof(search_pattern), "%s*", pk);

    HANDLE h_find = FindFirstFileA(search_pattern, &find_data);
    if (h_find == INVALID_HANDLE_VALUE) {
    	print_error("Failed to locate file\n");
        return NULL;
    }

    if(!hplc_metadata(find_data.cFileName,meta))
    	return NULL;
    FILE *fp = fopen(find_data.cFileName, "r");
    FindClose(h_find);
    return fp;

#else
    DIR *dir = opendir(".");
    if (dir == NULL) {
    	print_error("Failed to open directory\n");
        return NULL;
    }

    struct dirent *entry;
    FILE *fp = NULL;

    while ((entry = readdir(dir)) != NULL) {
        // Compare the first 7 characters of the filename against the PK prefix
        if (strncmp(entry->d_name, pk, PK_LEN) == 0) {
            fp = fopen(entry->d_name, "r");
	    if(!hplc_metadata(entry->d_name,meta)){
	    	fclose(fp);
    		closedir(dir);
		return NULL;
	    }
            break;
        }
    }

    closedir(dir);
    return fp;
#endif
}
